function f = HS43_f(x)
f = x(1).^2 - 5*x(1) + x(2).^2 - 5*x(2) + 2*x(3).^2 - 21*x(3) + x(4).^2 + 7*x(4);
end

function g = HS43_g(x)
g = zeros(4, 1);
g(1) = 2*x(1) - 5;
g(2) = 2*x(2) - 5;
g(3) = 4*x(3) - 21;
g(4) = 2*x(4) + 7;
end

function c = HS43_c(x)
c = zeros(3, 1);
c(1) = -x(1).^2 - x(1) - x(2).^2 + x(2) - x(3).^2 - x(3) - x(4).^2 + x(4) + 8;
c(2) = -x(1).^2 + x(1) - 2*x(2).^2 - x(3).^2 - 2*x(4).^2 + x(4) + 10;
c(3) = -2*x(1).^2 - 2*x(1) - x(2).^2 + x(2) - x(3).^2 + x(4) + 5;
end

function J = HS43_J(x)
J = zeros(3, 4);
J(1, 1) = -2*x(1) - 1;
J(1, 2) = 1 - 2*x(2);
J(1, 3) = -2*x(3) - 1;
J(1, 4) = 1 - 2*x(4);
J(2, 1) = 1 - 2*x(1);
J(2, 2) = -4*x(2);
J(2, 3) = -2*x(3);
J(2, 4) = 1 - 4*x(4);
J(3, 1) = -4*x(1) - 2;
J(3, 2) = 1 - 2*x(2);
J(3, 3) = -2*x(3);
J(3, 4) = 1;
end
